import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.Camera{CameraEntityUniqueID: 300, TargetPlayerUniqueID: -1}
CAMERA = bytes.fromhex("d80401")

# generated by gophertunnel b8bd735:
# &packet.Camera{CameraEntityUniqueID: -8589934592, TargetPlayerUniqueID: 0}
CAMERA_WIDE = bytes.fromhex("ffffffff3f00")

GOLDENS = [
    pytest.param(v2225.CameraPacket(camera_id=300, target_player_id=-1), CAMERA, id="camera"),
    pytest.param(v2225.CameraPacket(camera_id=-8589934592, target_player_id=0), CAMERA_WIDE, id="wide-camera-id"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_camera_is_packet_73(version):
    assert version.PACKETS[73] is version.CameraPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_decodes_from_its_golden(packet, golden):
    assert v2225.CameraPacket.from_bytes(golden) == packet
